-- ========================================================

-- Vector3
-- 并非从设备中读取到的 Vector2 原始值, 而是一个 world-space vec3, 角色能直接朝着这个方向运行 
local moveInputFromDevice = Vector3.zero
local moveInputFromCode = Vector3( 0,0,1 )



local inputMode = InputMode.FromDevice


-- 外部希望 moveInput 向量被约束到的 模长区间
local moveInputMagnitude = {}
moveInputMagnitude.expectedMin = 0.0 
moveInputMagnitude.expectedMax = 1.0
-- 一个平滑的, 不断逼近 moveInputTargetMagnitude 的值; 也是实际影响 moveInput 的约束值
moveInputMagnitude.smoothMin = 0.0 
moveInputMagnitude.smoothMax = 1.0

moveInputMagnitude.smoothSpeed = 1.5
moveInputMagnitude.isDirty = false -- 脏了就要更新


-- 上一次记录的 帧位移值 [0,1] 走路->跑步; 
-- !!! 注意: 当角色停下后, 此值保留最后一次位移帧的值 (非0)
local cachedMoveMagnitude = 0 


-- ========================================================

-- 本质就是把公共参数重置
function InputManager.Init()
    moveInputFromDevice = Vector3.zero
    moveInputFromCode = Vector3( 0,0,1 )

    inputMode = InputMode.FromDevice

    moveInputMagnitude.expectedMin = 0.0 
    moveInputMagnitude.expectedMax = 1.0

    moveInputMagnitude.smoothMin = 0.0 
    moveInputMagnitude.smoothMax = 1.0

    moveInputMagnitude.smoothSpeed = 1.5
    moveInputMagnitude.isDirty = false -- 脏了就要更新

    cachedMoveMagnitude = 0
end




function InputManager.SelfUpdate()
    InputManager.UpdateMoveInputMagnitude()
    --- ...
end



function InputManager.UpdateMoveInputMagnitude()
    if moveInputMagnitude.isDirty == false then 
        return 
    end 
    -- 平滑:
    local speed = moveInputMagnitude.smoothSpeed * Time.deltaTime
    moveInputMagnitude.smoothMin = Mathf.MoveTowards( moveInputMagnitude.smoothMin, moveInputMagnitude.expectedMin, speed )
    moveInputMagnitude.smoothMax = Mathf.MoveTowards( moveInputMagnitude.smoothMax, moveInputMagnitude.expectedMax, speed )

    -- 足够接近时解除 dirty
    if      DreamSpaceLuaUtils.CloseEnough( moveInputMagnitude.smoothMin, moveInputMagnitude.expectedMin, 0.001 ) == true 
        and DreamSpaceLuaUtils.CloseEnough( moveInputMagnitude.smoothMax, moveInputMagnitude.expectedMax, 0.001 ) == true 
    then 
        moveInputMagnitude.isDirty = false
    end 
end 



-- ========================================================

function InputManager.SetInputMode( inputMode_ )
    inputMode = inputMode_
end

function InputManager.GetInputMode()
    return inputMode
end


-- 不想设置的参数可写入 nil, 无效参数会被屏蔽掉
function InputManager.SetMoveInputMagnitudeConstraint( min_, max_ )
    if type(min_) == "number" and (min_>=0.0) and (min_<=1.0) then 
        moveInputMagnitude.expectedMin = min_
    end 
    if type(max_) == "number" and (max_>=0.0) and (max_<=1.0) then 
        moveInputMagnitude.expectedMax = max_
    end 
    assert( moveInputMagnitude.expectedMin <= moveInputMagnitude.expectedMax )

    moveInputMagnitude.isDirty = true -- 不管是不是真的更新数据, 都置脏
end




function InputManager.SetMoveInputFromDevice( moveInput_ )
    moveInputFromDevice = moveInput_
end


function InputManager.SetMoveInputFromCode( moveInput_ )
    moveInputFromCode = moveInput_
end


-- 是否有 有效的 移动输入值
function InputManager.IsMoveInputNotZero()
    if DreamSpaceStates.CanRoleMove() == false then 
        return false
    end 

    if inputMode == InputMode.FromDevice then 
        return moveInputFromDevice.magnitude > 0.00001
    elseif inputMode == InputMode.FromCode  then
        return moveInputFromCode.magnitude > 0.00001
    else 
        printError( " inputMode 类型异常 " .. tostring(inputMode) ) 
        return Vector3( 0,0,1 )
    end 
end



function InputManager.GetMoveInput()

    local tgtVec = Vector3( 0,0,1 )
    if inputMode == InputMode.FromDevice then 
        tgtVec = moveInputFromDevice
    elseif inputMode == InputMode.FromCode  then
        tgtVec = moveInputFromCode
    else 
        printError( " inputMode 类型异常 " .. tostring(inputMode) ) 
    end 

    local retVec = InputManager.RestrictMoveInputSpeed( tgtVec )
    cachedMoveMagnitude = retVec.magnitude
    return retVec
end


-- 约束 移动速度, 从而让角色 只能走路 或 只能跑步
function InputManager.RestrictMoveInputSpeed( moveInput_ )
    local tgtMag = Mathf.Clamp( moveInput_.magnitude, moveInputMagnitude.smoothMin, moveInputMagnitude.smoothMax )
    --print( "tgtMag = " .. tgtMag )
    return moveInput_.normalized * tgtMag
end



function InputManager.GetCachedMoveMagnitude()

    return cachedMoveMagnitude
end

return InputManager

